import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter_test/flutter_test.dart';

/// Integrity checks for assets/champions_seed.json (the Champions Pokédex
/// roster generated by tool/build_champions_from_champout.js from the
/// projectpokemon/champout datamine).
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  late Map<String, dynamic> champions;
  late List<dynamic> pokedex;
  late List<dynamic> items;

  setUpAll(() async {
    champions =
        jsonDecode(await rootBundle.loadString('assets/champions_seed.json'))
            as Map<String, dynamic>;
    pokedex =
        jsonDecode(await rootBundle.loadString('assets/pokedex_seed.json'))
            as List<dynamic>;
    items = jsonDecode(await rootBundle.loadString('assets/items_seed.json'))
        as List<dynamic>;
  });

  group('champions_seed.json integrity', () {
    test('has a pokemon roster and an items list', () {
      expect(champions['pokemon'], isA<List<dynamic>>());
      expect(champions['items'], isA<List<dynamic>>());
    });

    test('roster size is sane and grows with game updates', () {
      final roster = (champions['pokemon'] as List<dynamic>)
          .cast<Map<String, dynamic>>();
      // 353 champout forms after cosmetic collapse; moves with game patches.
      expect(roster.length, inInclusiveRange(340, 380));
    });

    test('every roster id exists in pokedex_seed.json', () {
      final seedIds = {for (final p in pokedex.cast<Map>()) p['id'] as int};
      for (final p in (champions['pokemon'] as List<dynamic>)
          .cast<Map<String, dynamic>>()) {
        expect(
          seedIds.contains(p['id'] as int),
          isTrue,
          reason: 'roster id ${p['id']} (${p['name']}) missing from the seed',
        );
        expect(
          seedIds.contains(p['dex'] as int),
          isTrue,
          reason:
              'roster dex ${p['dex']} (${p['name']}) missing from the seed',
        );
      }
    });

    test('roster entries contain valid abilities lists', () {
      final roster = (champions['pokemon'] as List<dynamic>)
          .cast<Map<String, dynamic>>();
      for (final p in roster) {
        expect(p['abilities'], isA<List<dynamic>>(),
            reason: 'pokemon ${p['name']} (#${p['id']}) must have abilities list');
        final abilities = p['abilities'] as List<dynamic>;
        expect(abilities, isNotEmpty,
            reason: 'pokemon ${p['name']} (#${p['id']}) has empty abilities');
      }
    });

    test('no duplicate roster ids and names are display-style', () {
      final seenIds = <int>{};
      for (final p in (champions['pokemon'] as List<dynamic>)
          .cast<Map<String, dynamic>>()) {
        final id = p['id'] as int;
        expect(seenIds.add(id), isTrue, reason: 'duplicate roster id $id');
        final name = p['name'] as String;
        // Seed names are display-style: capitalized, no snake_case slugs.
        expect(name.isNotEmpty, isTrue, reason: 'empty roster name for id $id');
        expect(
          name[0],
          equals(name[0].toUpperCase()),
          reason: 'roster name "$name" is not display-style',
        );
        expect(name.contains('_'), isFalse,
            reason: 'roster name "$name" looks like a slug');
      }
    });

    test('spot checks: base forms and known forms resolve to seed rows', () {
      final roster = (champions['pokemon'] as List<dynamic>)
          .cast<Map<String, dynamic>>();
      int idOf(String name) => roster
          .firstWhere((p) => p['name'] == name)['id'] as int;

      expect(idOf('Venusaur'), equals(3));
      expect(idOf('Mega Venusaur'), equals(10033));
      expect(idOf('Mega Charizard X'), equals(10034));
      // Regional/override-free signature matching: "Raichu-Alola" maps to the
      // seed's "Alolan Raichu" row; "Tauros-Paldea Combat" to the Combat Breed.
      expect(idOf('Alolan Raichu'), greaterThan(0));
      expect(idOf('Combat Breed Paldean Tauros'), greaterThan(0));
      // Game-authoritative roster facts: the datamine has no base Floette and
      // no Patrat (champsmeta listed both), but has Eternal Floette.
      expect(idOf('Eternal Floette'), equals(10061));
      expect(
        roster.where((p) => p['id'] == 504 || p['id'] == 670),
        isEmpty,
        reason: 'Patrat (#504) and base Floette (#670) are not in the game data',
      );
    });

    test('legal items list is populated with display-style names', () {
      final names =
          (champions['items'] as List<dynamic>).cast<String>();
      expect(names.length, greaterThanOrEqualTo(150));
      final seedItemNames = {
        for (final i in items.cast<Map>())
          (i['name'] as String).toLowerCase().replaceAll(RegExp('[^a-z0-9]'), '')
      };
      for (final name in names) {
        expect(name.isNotEmpty, isTrue);
        expect(name.contains('_'), isFalse,
            reason: 'item name "$name" looks like a slug');
      }
      // Most champions items should exist in the app's item seed so the
      // Items screen can actually display them in champions mode.
      final matchable = names
          .where((n) => seedItemNames
              .contains(n.toLowerCase().replaceAll(RegExp('[^a-z0-9]'), '')))
          .length;
      expect(matchable, greaterThanOrEqualTo(150),
          reason: 'most champions items must exist in items_seed.json');
    });
  });
}
